            reverted = !ok;
        } catch {
            reverted = true;
        }

        uint256 fromBalAfter = c.balanceOf(from);
        uint256 toBalAfter = c.balanceOf(to);
        uint256 allowedAfter = c.allowance(from, to);

        assert(
            toBalAfter == (toBalBefore + amount) &&
            fromBalAfter == (fromBalBefore2 - amount) &&
            allowedAfter == (allowedBefore - amount) &&
            !reverted
        );
    }

    receive() external payable {}
}

